          const g = gcd(a, b);
          const [x, y] = [a / g, b / g];
          return ["צמצמו את היחס", `${a} : ${b}`, withWrong(`${x} : ${y}`, [`${y} : ${x}`, `${x} : ${y + 1}`, `${x + 1} : ${y}`])];
