  /* ---------- השיעורים הארוכים: כישורי חיים, גוף האדם, נפלאות הבריאה ---------- */

  // A topic of one long lesson (ready-lessons.js), and the words of its
  // matching board, short enough to fit a tile.
  function longLessonTopic(id, title, lesson, pairs, exercises) {
    return {
      id,
      title,
      lessons: [lesson],
      exercises: [
        { id: "words", type: "match", title: "מילים חשובות – התאמה", instructions: "לחצו על מילה ואז על ההסבר שלה.", level: 1, boardSize: 6, pairs: pairs.map(([a, b]) => ({ a, b })) },
        ...exercises,
      ],
    };
  }

