      T([
        ["עיגול ריק אומר שהמספר עצמו לא בפנים", "", true],
        ["עיגול מלא אומר שהמספר עצמו בפנים", "", true],
        ["במספר חיובי הסימן מתהפך", "", false, "הסימן מתהפך רק במספר שלילי"],
        ["כשמחברים מספר לשני הצדדים, הסימן נשאר", "", true],
        ["המספר 3 פותר את $x > 3$", "", false, "$x$ גדול מ־3, ו־3 לא גדול מעצמו"],
        ["המספר 3 פותר את $x ≥ 3$", "", true],
        ["לאי־שוויון יש תמיד פתרון אחד בלבד", "", false, "יש לו בדרך כלל הרבה פתרונות"],
        ["כשמחלקים ב־$-2$, הסימן מתהפך", "", true],
      ])
